class Solution {
    public int equalCountSubstrings(String s, int count) {
        int n = s.length(), ans = 0;
        for (int u = 1; u <= 26 && (long) u * count <= n; u++) {
            int len = u * count;
            int[] cnt = new int[26];
            int exact = 0;
            for (int i = 0; i < n; i++) {
                int c = s.charAt(i) - 'a';
                if (cnt[c] == count) exact--;
                if (++cnt[c] == count) exact++;
                if (i >= len) {
                    int d = s.charAt(i - len) - 'a';
                    if (cnt[d] == count) exact--;
                    if (--cnt[d] == count) exact++;
                }
                if (i >= len - 1 && exact == u) ans++;
            }
        }
        return ans;
    }
}
